"""LUA patch scaffolding for PS2 Classics."""

from __future__ import annotations

from pathlib import Path

BASIC_TEMPLATE = '''-- {title_id} / {game_name}
-- Generated by PS22PSX LUA maker
-- Docs: https://www.psdevwiki.com/ps4/PS2_Classics_Emulator

local eeObj = getEEObject()
local emuObj = getEmuObject()

local patcher = function()
  -- Example: nop a problematic store
  -- eeObj.WriteMem32(0x00100000, 0x00000000)
end

emuObj.AddVsyncHook(patcher)
'''

UPSCALE_HINT = '''-- Optional GS helpers (requires matching config flags)
-- --gs-uprender=edgesmooth
-- --gs-upscale=smooth
'''


def create_lua(
    title_id: str,
    game_name: str = "Unknown",
    *,
    include_upscale_hint: bool = False,
) -> str:
    body = BASIC_TEMPLATE.format(title_id=title_id, game_name=game_name)
    if include_upscale_hint:
        body += "\n" + UPSCALE_HINT
    return body


def write_lua(path: Path, title_id: str, game_name: str = "Unknown", **kwargs) -> Path:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(create_lua(title_id, game_name, **kwargs), encoding="utf-8")
    return path
